package com.haddol7.photoviewer.ui;

import android.app.AlertDialog;
import android.content.Context;
import android.graphics.*;
import android.graphics.drawable.GradientDrawable;
import android.text.TextUtils;
import android.view.*;
import android.view.inputmethod.EditorInfo;
import android.widget.*;
import com.haddol7.photoviewer.data.PhotoRepository;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.function.Consumer;

/** Native chat timeline; the server owns history and request-id deduplication. */
public final class ChatWorkspace extends LinearLayout {
    private final PhotoRepository api;private final Consumer<String> status;private final String preferenceKey;
    private final ExecutorService network=Executors.newSingleThreadExecutor(),pictures=Executors.newFixedThreadPool(2);
    private final ScrollView scroll;private final LinearLayout messages;private final EditText input;private final Button send,history,newChat,scopeButton;
    private JSONArray turns=new JSONArray(),profiles=new JSONArray();private String active="",profile="",start="",end="",basis="processed";private boolean candidates,busy,ready;private Long before;private int generation;
    private interface Done{void accept(JSONObject value)throws Exception;}
    public ChatWorkspace(Context context,PhotoRepository repository,String owner,String origin,String contextProfile,Consumer<String> report){
        super(context);setOrientation(VERTICAL);api=repository;status=report;profile=contextProfile;preferenceKey="chat:"+origin+":"+owner;
        LinearLayout toolbar=UiKit.row(context);TextView title=UiKit.text(context,"AI 질문",20,true);toolbar.addView(title,new LayoutParams(0,-2,1));history=action("대화 기록",this::showHistory);newChat=action("새 대화",this::newChat);toolbar.addView(history);toolbar.addView(newChat);addView(toolbar);
        scopeButton=action("전체 기록",this::scope);scopeButton.setTextSize(11);scopeButton.setMinHeight(dp(32));scopeButton.setMinimumHeight(dp(32));addView(scopeButton,new LayoutParams(-1,dp(34)));
        scroll=new ScrollView(context);scroll.setFillViewport(true);messages=UiKit.column(context);messages.setPadding(dp(3),dp(12),dp(3),dp(8));scroll.addView(messages);addView(scroll,new LayoutParams(-1,0,1));
        LinearLayout composer=UiKit.row(context);input=UiKit.input(context,"관측 기록에 질문하세요",android.text.InputType.TYPE_CLASS_TEXT);input.setContentDescription("채팅 질문");input.setImeOptions(EditorInfo.IME_ACTION_SEND);composer.addView(input,new LayoutParams(0,dp(48),1));send=action("보내기",this::send);send.setContentDescription("고정 완료 버튼");send.setBackgroundTintList(android.content.res.ColorStateList.valueOf(UiKit.GREEN));send.setTextColor(UiKit.WHITE);composer.addView(send,new LayoutParams(dp(76),dp(48)));addView(composer);addView(UiKit.text(context,"전송 시 검색과 AI 답변에 API 사용료가 발생할 수 있습니다.",9,false));
        input.setOnEditorActionListener((view,action,event)->{if(action==EditorInfo.IME_ACTION_SEND){send();return true;}return false;});controls();render();
        post(()->run("대화 기록을 불러옵니다.",()->api.historyProfiles(),data->{profiles=data.getJSONArray("results");if(!contextProfile.isEmpty()){ready=true;controls();scopeLabel();return;}String previous=context.getSharedPreferences("ChatWorkspace",0).getString(preferenceKey,"");if(!previous.isEmpty()){load(previous,true);return;}run("저장된 대화를 확인합니다.",()->api.conversations(0),list->{JSONArray rows=list.getJSONArray("results");ready=true;if(rows.length()>0)load(rows.getJSONObject(0).getString("id"),true);else{controls();status.accept("새 질문을 입력하세요.");}});}));
    }
    private int dp(float value){return UiKit.dp(getContext(),value);}private Button action(String text,Runnable task){return UiKit.button(getContext(),text,v->task.run());}
    private void controls(){send.setEnabled(ready&&!busy);newChat.setEnabled(!busy);history.setEnabled(!busy);scopeButton.setEnabled(!busy);}
    private void run(String label,Callable<JSONObject> work,Done done){if(busy||network.isShutdown())return;busy=true;controls();status.accept(label);network.execute(()->{try{JSONObject value=work.call();post(()->{if(!isAttachedToWindow())return;busy=false;controls();try{done.accept(value);}catch(Exception error){failed(error);}});}catch(Exception error){post(()->{if(!isAttachedToWindow())return;busy=false;controls();failed(error);});}});}
    private void failed(Exception error){for(int i=0;i<turns.length();i++){JSONObject turn=turns.optJSONObject(i);if("pending".equals(turn.optString("state")))try{turn.put("state","failed");}catch(JSONException ignored){/* fixed key */}}render();status.accept(error.getMessage()==null?"대화 기록을 확인해주세요.":error.getMessage());ready=true;controls();}
    private void remember(){getContext().getSharedPreferences("ChatWorkspace",0).edit().putString(preferenceKey,active).apply();}
    private void newChat(){if(busy)return;active="";turns=new JSONArray();before=null;profile=start=end="";basis="processed";candidates=false;input.setText("");remember();render();scopeLabel();status.accept("새 대화입니다.");}
    private void load(String key,boolean restoreScope){run("대화를 불러옵니다.",()->api.conversation(key,null),data->{active=data.getString("id");turns=data.getJSONArray("turns");before=data.isNull("next_before")?null:data.getLong("next_before");if(restoreScope){JSONObject saved=data.optJSONObject("scope");if(saved!=null){profile=saved.optString("profile");start=saved.optString("start");end=saved.optString("end");basis=saved.optString("date_basis","processed");candidates=saved.optBoolean("include_candidates");}}ready=true;remember();render();scopeLabel();controls();bottom();status.accept("저장된 대화를 불러왔습니다.");});}
    private void showHistory(){historyPage(0,new ArrayList<>(),new ArrayList<>());}
    private void historyPage(int offset,List<String> names,List<String> keys){run("대화 목록을 불러옵니다.",()->api.conversations(offset),data->{JSONArray rows=data.getJSONArray("results");for(int i=0;i<rows.length();i++){JSONObject row=rows.getJSONObject(i);names.add(row.getString("title"));keys.add(row.getString("id"));}if(!data.isNull("next_offset")){historyPage(data.getInt("next_offset"),names,keys);return;}if(names.isEmpty()){status.accept("저장된 대화가 없습니다.");return;}new AlertDialog.Builder(getContext()).setTitle("대화 기록").setItems(names.toArray(new String[0]),(dialog,position)->load(keys.get(position),true)).setNegativeButton("닫기",null).show();status.accept("불러올 대화를 선택하세요.");});}
    private String now(){java.text.SimpleDateFormat format=new java.text.SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSS'Z'",Locale.US);format.setTimeZone(TimeZone.getTimeZone("UTC"));return format.format(new Date());}
    private void send(){if(busy||!ready)return;String question=input.getText().toString().trim();if(question.isEmpty()||question.length()>400){status.accept("질문은 1~400자로 입력해주세요.");return;}String requestId=UUID.randomUUID().toString();try{turns.put(new JSONObject().put("id",Long.MAX_VALUE).put("request_id",requestId).put("question",question).put("state","pending").put("created_at",now()));input.setText("");render();bottom();hideKeyboard();if(active.isEmpty()){run("대화를 준비합니다.",()->api.createConversation(),data->{active=data.getString("id");remember();submit(question,requestId);});}else submit(question,requestId);}catch(JSONException error){failed(error);}}
    private void submit(String question,String requestId)throws JSONException{
        // Automatic APIs are authorized for the owner's app sends, not for Codex tests.
        JSONObject packet=new JSONObject().put("question",question).put("profile",profile).put("start",start).put("end",end).put("date_basis",basis).put("include_candidates",candidates).put("semantic",true).put("generate",true).put("conversation_id",active).put("request_id",requestId);
        run("기록을 확인하고 있습니다.",()->api.historyQuestion(packet),result->{for(int i=0;i<turns.length();i++){JSONObject turn=turns.getJSONObject(i);if(requestId.equals(turn.optString("request_id"))){turn.put("id",result.getJSONObject("chat").getLong("turn_id")).put("state","complete").put("result",result);break;}}render();bottom();status.accept("대화가 저장되었습니다.");});
    }
    private void hideKeyboard(){((android.view.inputmethod.InputMethodManager)getContext().getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(getWindowToken(),0);input.clearFocus();}
    private void bottom(){scroll.post(()->scroll.fullScroll(View.FOCUS_DOWN));}
    private TextView bubble(String text){TextView view=UiKit.text(getContext(),text,14,false);view.setPadding(dp(13),dp(10),dp(13),dp(10));GradientDrawable background=new GradientDrawable();background.setColor(UiKit.SAGE);background.setCornerRadius(dp(15));view.setBackground(background);view.setMaxWidth(getResources().getDisplayMetrics().widthPixels-dp(78));return view;}
    private void render(){generation++;messages.removeAllViews();scopeLabel();if(before!=null){messages.addView(action("이전 대화 더 보기",()->{long key=before;run("이전 대화를 불러옵니다.",()->api.conversation(active,key),data->{JSONArray older=data.getJSONArray("turns"),merged=new JSONArray();for(int i=0;i<older.length();i++)merged.put(older.get(i));for(int i=0;i<turns.length();i++)merged.put(turns.get(i));turns=merged;before=data.isNull("next_before")?null:data.getLong("next_before");render();});}));}
        if(turns.length()==0){LinearLayout welcome=UiKit.column(getContext());welcome.setPadding(dp(12),dp(30),dp(12),dp(24));welcome.addView(UiKit.text(getContext(),"관측 기록에 물어보세요",22,true));welcome.addView(UiKit.text(getContext(),"관련 영상과 근거 사진을 함께 찾아드립니다.",12,false));String[][] examples={{"출국 장면","비행기를 타러 떠나는 장면을 찾아줘"},{"기자 설명","기자들에게 국정 현안을 설명하는 영상"},{"안보 회의","여러 나라가 모여 안보 문제를 논의하는 영상"}};for(String[] row:examples)welcome.addView(action(row[0],()->{input.setText(row[1]);input.requestFocus();}));messages.addView(welcome);return;}
        for(int i=0;i<turns.length();i++){JSONObject turn=turns.optJSONObject(i);TextView question=bubble(turn.optString("question"));LayoutParams questionLayout=new LayoutParams(-2,-2);questionLayout.gravity=Gravity.END;questionLayout.topMargin=dp(14);messages.addView(question,questionLayout);JSONObject result=turn.optJSONObject("result");messages.addView(UiKit.text(getContext(),result!=null&&"generated".equals(result.optJSONObject("llm").optString("status"))?"AI 답변":"기록 도우미",10,true));if(!"complete".equals(turn.optString("state"))||result==null){messages.addView(UiKit.text(getContext(),"pending".equals(turn.optString("state"))?"기록을 확인하고 있습니다.":"응답을 확인하지 못했습니다. 저장된 대화를 확인해주세요.",13,false));if(!"pending".equals(turn.optString("state")))messages.addView(action("저장된 응답 확인",()->{if(active.isEmpty())showHistory();else load(active,false);}));continue;}JSONObject llm=result.optJSONObject("llm");String answer="generated".equals(llm.optString("status"))?llm.optString("text"):HistoryPresentation.shortAnswer(result.optString("answer"));TextView reply=UiKit.text(getContext(),answer,14,false);reply.setContentDescription("채팅 답변");reply.setLineSpacing(dp(3),1.1f);messages.addView(reply);JSONArray evidence=result.optJSONArray("evidence");if(evidence!=null&&evidence.length()>0){messages.addView(UiKit.text(getContext(),"근거 사진 "+evidence.length()+"장",10,false));LinearLayout row=UiKit.row(getContext());for(int at=0;at<Math.min(2,evidence.length());at++)UiKit.weighted(row,evidence(evidence.optJSONObject(at)));messages.addView(row);if(evidence.length()>2){LinearLayout more=UiKit.column(getContext());more.setVisibility(GONE);messages.addView(action("근거 "+(evidence.length()-2)+"장 더 보기",()->{if(more.getChildCount()==0)for(int at=2;at<evidence.length();at++)more.addView(evidence(evidence.optJSONObject(at)));more.setVisibility(VISIBLE);}));messages.addView(more);}}messages.addView(UiKit.text(getContext(),MonitoringTime.format(turn.optString("created_at")),9,false));}
    }
    private LinearLayout evidence(JSONObject row){LinearLayout tile=UiKit.card(getContext());tile.setPadding(dp(5),dp(5),dp(5),dp(5));ImageView photo=new ImageView(getContext());photo.setScaleType(ImageView.ScaleType.CENTER_CROP);photo.setContentDescription("답변 근거 사진");tile.addView(photo,new LayoutParams(-1,dp(96)));photo(photo,row.optString("image_url"));TextView label=UiKit.text(getContext(),row.optString("source"),10,false);label.setMaxLines(2);label.setEllipsize(TextUtils.TruncateAt.END);tile.addView(label);tile.setOnClickListener(v->{LinearLayout box=UiKit.column(getContext());ImageView large=new ImageView(getContext());large.setScaleType(ImageView.ScaleType.FIT_CENTER);box.addView(large,new LayoutParams(-1,Math.max(dp(120),Math.min(dp(340),getHeight()-dp(180)))));photo(large,row.optString("image_url"));box.addView(UiKit.text(getContext(),"분석 "+MonitoringTime.format(row.optString("processed_at")),11,false));new AlertDialog.Builder(getContext()).setTitle(row.optString("source")).setView(box).setPositiveButton("닫기",null).show();});return tile;}
    private void photo(ImageView target,String url){if(url.isEmpty()||"null".equals(url))return;int ticket=generation;pictures.execute(()->{if(!isAttachedToWindow()||ticket!=generation)return;try{byte[] bytes=api.downloadPhoto(url);BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,bounds);BitmapFactory.Options sample=new BitmapFactory.Options();sample.inSampleSize=Math.max(1,Math.max(bounds.outWidth,bounds.outHeight)/600);Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length,sample);post(()->{if(isAttachedToWindow()&&ticket==generation)target.setImageBitmap(bitmap);});}catch(Exception ignored){post(()->target.setContentDescription("사진을 불러오지 못했습니다."));}});}
    private void scopeLabel(){String name="전체 기록";for(int i=0;i<profiles.length();i++){JSONObject p=profiles.optJSONObject(i);if(profile.equals(p.optString("key")))name=p.optString("name");}scopeButton.setText(name+(start.isEmpty()&&end.isEmpty()?"":" / 날짜 지정")+(candidates?" / 후보 포함":""));}
    private void scope(){LinearLayout box=UiKit.column(getContext());box.setPadding(dp(18),dp(4),dp(18),0);List<String> names=new ArrayList<>();names.add("전체 인물");int selected=0;for(int i=0;i<profiles.length();i++){JSONObject p=profiles.optJSONObject(i);names.add(p.optString("name"));if(profile.equals(p.optString("key")))selected=i+1;}Spinner person=new Spinner(getContext());person.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,names));person.setSelection(selected);box.addView(person);Spinner time=new Spinner(getContext());time.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,new String[]{"분석일","원본 촬영일"}));time.setSelection("recorded".equals(basis)?1:0);box.addView(time);EditText from=UiKit.input(getContext(),"시작일 YYYY-MM-DD",android.text.InputType.TYPE_CLASS_TEXT),until=UiKit.input(getContext(),"종료일 YYYY-MM-DD",android.text.InputType.TYPE_CLASS_TEXT);from.setText(start);until.setText(end);box.addView(from);box.addView(until);Spinner state=new Spinner(getContext());state.setAdapter(new ArrayAdapter<>(getContext(),android.R.layout.simple_spinner_dropdown_item,new String[]{"확인된 인물만","미확인 후보 포함"}));state.setSelection(candidates?1:0);box.addView(state);new AlertDialog.Builder(getContext()).setTitle("검색 범위").setView(box).setNegativeButton("취소",null).setNeutralButton("전체 기록",(d,w)->{profile=start=end="";basis="processed";candidates=false;scopeLabel();}).setPositiveButton("적용",(d,w)->{profile=person.getSelectedItemPosition()==0?"":profiles.optJSONObject(person.getSelectedItemPosition()-1).optString("key");start=from.getText().toString().trim();end=until.getText().toString().trim();basis=time.getSelectedItemPosition()==0?"processed":"recorded";candidates=state.getSelectedItemPosition()==1;scopeLabel();}).show();}
    @Override protected void onDetachedFromWindow(){generation++;network.shutdown();pictures.shutdown();super.onDetachedFromWindow();}
}
